<script setup>
import {computed,onMounted,onUnmounted,ref} from 'vue'
import {api,notify,state} from '../lib'
import Icon from './Icon.vue'
import Modal from './Modal.vue'
import MediaCategoryEditor from './MediaCategoryEditor.vue'
import NamingRuleEditor from './NamingRuleEditor.vue'
import UpgradeRuleEditor from './UpgradeRuleEditor.vue'
const props=defineProps({kind:{type:String,required:true}})
const names={naming:'命名规则',categories:'媒体分类',upgrade:'洗版策略'},icons={naming:'FolderTree',categories:'Tags',upgrade:'MediaUpgrade'}
const title=computed(()=>names[props.kind]),items=ref([]),loaded=ref(false),busy=ref(false),editing=ref(null),deleting=ref(null),error=ref(''),catalog=ref(null),opening=ref(false),valid=ref(true)
let alive=true,ticket=0
onUnmounted(()=>{alive=false;ticket++})
async function load(){const run=++ticket,owner=state.username;try{const value=await api(`/rule-presets?kind=${props.kind}`);if(!Array.isArray(value))throw Error('预设列表格式异常');if(alive&&run===ticket&&owner===state.username){items.value=value;loaded.value=true}}catch(e){if(alive&&run===ticket)notify(e.message,true)}}
onMounted(load)
const field=computed(()=>({categories:'mediaCategory',naming:'naming',upgrade:'upgrade'})[props.kind])
const upgradeEditor=ref(null)
async function open(item){if(busy.value||opening.value)return;error.value='';valid.value=true;const owner=state.username;opening.value=true;try{if(!catalog.value)catalog.value=await api(`/${{categories:'media-categories',naming:'naming-rules',upgrade:'upgrade-rules'}[props.kind]}/catalog`);if(!alive||owner!==state.username)return;const value=item?JSON.parse(JSON.stringify(item)):{id:'',kind:props.kind,name:'',description:''};if(!value[field.value])value[field.value]=JSON.parse(JSON.stringify(catalog.value.defaults));editing.value=value}catch(e){if(alive)notify(e.message,true)}finally{if(alive)opening.value=false}}
async function save(){if(busy.value||!valid.value)return;busy.value=true;error.value='';const value=editing.value,owner=state.username;try{await api(value.id?`/rule-presets/${value.id}`:'/rule-presets',value.id?'PUT':'POST',{name:value.name,description:value.description,kind:props.kind,[field.value]:value[field.value]});if(!alive||owner!==state.username)return;editing.value=null;await load();notify('预设已保存')}catch(e){if(alive)error.value=e.message}finally{if(alive)busy.value=false}}
async function remove(){if(busy.value)return;busy.value=true;const value=deleting.value,owner=state.username;try{await api(`/rule-presets/${value.id}`,'DELETE');if(!alive||owner!==state.username)return;deleting.value=null;await load();notify('预设已删除')}catch(e){if(alive)notify(e.message,true)}finally{if(alive)busy.value=false}}
</script>
<template>
 <section class="rule-preset-list" :aria-label="title">
  <article v-for="item in items" :key="item.id" class="rule-preset-card" :data-config-path="`/rule-presets/${item.id}`" tabindex="0" :aria-label="`${title}预设 ${item.name}`" @click="open(item)" @keydown.enter.self="open(item)" @keydown.space.self.prevent="open(item)">
   <div class="rule-preset-symbol"><Icon :name="icons[kind]" :size="32"/></div>
   <div class="rule-preset-summary"><h2 :data-tooltip="item.name" data-tooltip-stationary>{{item.name}}</h2><span v-if="kind==='categories'" class="media-category-summary">剧集、电影 · {{Math.max(0,(item.mediaCategory?.directories?.length||2)-2)}} 个分类目录 · {{item.mediaCategory?.rules?.length||0}} 条规则</span><span class="rule-preset-kind">{{title}}规则</span></div>
   <div class="rule-preset-actions"><button class="icon-btn" :aria-label="`编辑预设 ${item.name}`" :disabled="busy||opening" @click.stop="open(item)" data-tooltip="编辑" data-tooltip-always><Icon name="Pencil"/></button><button class="icon-btn danger-text" :aria-label="`删除预设 ${item.name}`" :disabled="busy||items.length<=1" @click.stop="items.length>1&&(deleting=item)" :data-tooltip="items.length<=1?'至少保留一个预设':'删除'" data-tooltip-always><Icon name="Trash2"/></button></div>
  </article>
  <button class="rule-preset-add" :aria-label="`添加${title}预设`" :disabled="!loaded||busy||opening" @click="open()"><Icon name="Plus" :size="24"/><span>{{loaded?`添加${title}预设`:'正在读取预设…'}}</span></button>
 </section>
 <Modal v-if="editing" standard :title="`${editing.id?'编辑':'添加'}${title}预设`" @close="!busy&&(editing=null)"><form class="media-category-preset-form" :class="{'template-preset-form':kind!=='categories'}" @submit.prevent="save"><div class="modal-body rule-preset-form"><div class="rule-preset-header"><label>规则名称<input v-model.trim="editing.name" aria-label="规则名称" maxlength="200" required :disabled="busy"/></label><button v-if="kind==='upgrade'" type="button" class="btn rule-preset-reset" :disabled="busy" @click="upgradeEditor?.reset()"><Icon name="RotateCcw" :size="16"/>恢复默认洗版配置</button></div><MediaCategoryEditor v-if="kind==='categories'" v-model="editing.mediaCategory" :fields="catalog.fields" :disabled="busy" :error="error"/><NamingRuleEditor v-else-if="kind==='naming'" v-model="editing.naming" :catalog="catalog" :disabled="busy" @validity="valid=$event"/><UpgradeRuleEditor v-else-if="kind==='upgrade'" ref="upgradeEditor" v-model="editing.upgrade" :catalog="catalog" :disabled="busy"/><p v-if="error" class="error-message" role="alert">{{error}}</p></div><footer class="modal-footer"><button type="button" class="btn" :disabled="busy" @click="editing=null">取消</button><button class="btn primary" :disabled="busy||!valid||!editing.name.trim()"><Icon name="Check"/>保存</button></footer></form></Modal>
 <Modal v-if="deleting" confirmation :title="`删除${title}预设`" @close="!busy&&(deleting=null)"><div class="modal-body">确认删除预设「{{deleting.name}}」？</div><footer class="modal-footer"><button class="btn" :disabled="busy" @click="deleting=null">取消</button><button class="btn danger" :disabled="busy" @click="remove">确认删除</button></footer></Modal>
</template>
<style scoped>
@media(max-width:480px){.rule-preset-header .rule-preset-reset{font-size:12px;padding-inline:8px;gap:4px;white-space:nowrap}}
.template-preset-form :deep(.naming-token button:focus-visible){outline-width:1px;outline-color:color-mix(in srgb,var(--primary) 55%,transparent);outline-offset:-2px}
.rule-preset-list{display:grid;grid-template-columns:minmax(0,1fr);gap:16px;--preset-row-height:max(180px,calc((100dvh - 200px)/3))}
.rule-preset-card,.rule-preset-add{width:100%;min-width:0;min-height:var(--preset-row-height);border:1px solid var(--border);border-radius:12px;background:var(--surface);padding:28px;box-sizing:border-box}
.rule-preset-card{display:flex;align-items:center;gap:24px;cursor:pointer;transition:border-color .18s,background .18s}.rule-preset-card:hover{border-color:var(--primary)}.rule-preset-card:focus-visible,.rule-preset-add:focus-visible{outline:2px solid var(--primary);outline-offset:2px}
.rule-preset-symbol{display:grid;place-items:center;width:64px;height:64px;flex:none;background:var(--primary-soft);border-radius:14px;color:var(--primary)}.rule-preset-summary{min-width:0;flex:1}.rule-preset-summary h2{font-size:18px;line-height:28px;font-weight:600;margin:0 0 12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.rule-preset-summary p{margin:0;color:var(--muted);font-size:14px;line-height:24px;overflow:hidden;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow-wrap:anywhere;white-space:pre-wrap}.rule-preset-kind{display:inline-block;color:var(--muted);font-size:12px;margin-top:18px}.rule-preset-actions{display:flex;align-self:flex-start;gap:8px;flex:none}.rule-preset-actions .icon-btn{width:34px;height:36px}.rule-preset-add{display:flex;justify-content:center;align-items:center;gap:12px;border-style:dashed;color:var(--muted);background:transparent;font-size:16px;cursor:pointer}.rule-preset-add:hover:enabled{color:var(--primary);border-color:var(--primary);background:var(--primary-soft)}.rule-preset-add:disabled{cursor:default;opacity:.7}
.rule-preset-form{display:grid;align-content:start;gap:18px}.rule-preset-form input,.rule-preset-form textarea{width:100%}.rule-preset-form textarea{min-height:112px;resize:vertical}
.rule-preset-header{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:16px;align-items:end}.rule-preset-header label{min-width:0}.rule-preset-header input{height:40px;min-height:40px}.rule-preset-reset{height:40px;min-height:40px;justify-self:start;max-width:100%;white-space:normal}
.rule-preset-form :deep(.rule-editor-tabs),.rule-preset-form :deep(.media-category-tabs){display:grid!important;grid-auto-flow:column;grid-auto-columns:minmax(0,1fr);gap:6px}.rule-preset-form :deep([role=tab]){display:flex;align-items:center;justify-content:center;gap:8px;min-width:0;height:40px;min-height:40px}
.media-category-summary{display:block;color:var(--muted);font-size:12px;line-height:1.7;margin-top:12px}.media-category-preset-form{flex:1;display:flex;flex-direction:column;min-height:0;overflow:hidden}.media-category-preset-form>.rule-preset-form{flex:1;min-height:0;overflow:auto;scrollbar-width:none}.media-category-preset-form>.rule-preset-form::-webkit-scrollbar{display:none}.media-category-preset-form>.modal-footer{flex:none}.media-category-preset-form>.rule-preset-form>label:nth-child(2)>textarea{min-height:66px;height:66px;resize:vertical}
.media-category-summary{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
:global(.modal:has(>.media-category-preset-form)){display:flex;flex-direction:column;overflow:hidden}:global(.modal:has(>.media-category-preset-form)>.modal-header){flex:none}
:global(.modal.standard-modal:has(>.media-category-preset-form)){width:min(960px,calc(100vw - 32px));height:min(860px,calc(100dvh - 48px))}
.template-preset-form :deep(.rule-editor-tabs){display:flex;gap:6px;border-bottom:1px solid var(--border);padding-bottom:10px;flex-wrap:wrap}.template-preset-form :deep(.rule-editor-tabs button){min-height:40px;padding:8px 12px;border:1px solid transparent;border-radius:8px;background:none;color:var(--muted);cursor:pointer;font-size:13px}.template-preset-form :deep(.rule-editor-tabs button[aria-selected=true]){background:var(--primary-soft);border-color:var(--primary-soft);color:var(--primary)}.template-preset-form :deep(.rule-editor-help){font-size:12px;color:var(--muted);line-height:1.8}.template-preset-form :deep(.rule-sort-handle){display:grid;place-items:center;flex:none;width:26px;min-height:36px;border:0;background:none;color:inherit;cursor:grab;touch-action:none;user-select:none}.template-preset-form :deep(.rule-sort-handle:active){cursor:grabbing}.template-preset-form :deep(button:focus-visible){outline:2px solid var(--primary);outline-offset:2px}.template-preset-form :deep(.rule-editor-placeholder){padding:35px 12px;text-align:center;color:var(--muted);font-size:14px}
@media(max-width:760px){.rule-preset-card,.rule-preset-add{padding:18px}.rule-preset-card{gap:14px}.rule-preset-symbol{width:42px;height:48px;border-radius:10px}.rule-preset-symbol svg{width:26px;height:26px}.rule-preset-summary h2{font-size:16px;margin-bottom:8px}.rule-preset-summary p{font-size:13px;line-height:22px}.rule-preset-actions{gap:2px}.rule-preset-actions .icon-btn{width:28px}.rule-preset-kind{margin-top:12px}}
@media(prefers-reduced-motion:reduce){.rule-preset-card{transition:none}}
.rule-preset-add{background:var(--surface)}
</style>
